"\"\"\"Analyse des expériences E1 (prédiction de champ) et E2 (distillation).\n\nSorties : tableaux médians appariés par graine, différences gén vs concurrents, et lecture.\n\"\"\"\nimport json\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef med(xs):\n    return float(np.median(xs))\n\n\ndef e1_analysis():\n    rows = json.loads((ROOT / \"results\" / \"e1_field.json\").read_text())\n    print(\"=\" * 78)\n    print(\"E1 — Prédiction du champ de poids du parent (erreur relative ‖pred−W*‖/‖W*‖, médiane)\")\n    print(\"=\" * 78)\n    methods = [\"gen\", \"genfree\", \"hyp\", \"lerp\", \"mean\", \"nearest\"]\n    for kind in (\"gauss\", \"mlp\"):\n        for hold in (2, 5):\n            sub = [r for r in rows if r[\"kind\"] == kind and r[\"hold\"] == hold]\n            line = {m: med([r[m] for r in sub]) for m in methods}\n            tag = \"interpolation\" if hold == 2 else \"extrapolation\"\n            print(f\"\\nparent {kind} — couche tenue dehors : {hold} ({tag})\")\n            print(\"  \" + \"  \".join(f\"{m}={line[m]:.4f}\" for m in methods))\n            # apparié par graine : gen − concurrent\n            for m in (\"genfree\", \"hyp\", \"lerp\"):\n                d = [r[\"gen\"] - r[m] for r in sub]\n                wins = sum(x < 0 for x in d)\n                print(f\"  Δ(gen−{m}): médiane {med(d):+.4f}  [{wins}/{len(d)} graines où gen gagne]\")\n    # qualité d'ajustement (sanity : tout le monde s'ajuste bien sur les couches observées)\n    for kind in (\"gauss\", \"mlp\"):\n        for m in (\"gen\", \"genfree\", \"hyp\"):\n            sub = [r for r in rows if r[\"kind\"] == kind and r[m + \"_fit\"] is not None]\n            print(f\"fit RMSE médian {kind}/{m}: {med([r[m + '_fit'] for r in sub]):.4f}\")\n\n\ndef e2_analysis():\n    files = sorted((ROOT / \"results\" / \"e2_distill\").glob(\"*.json\"))\n    rows = [json.loads(f.read_text()) for f in files]\n    methods = [\"gen\", \"genfree\", \"lora\", \"hyp\", \"albert\"]\n    print(\"\\n\" + \"=\" * 78)\n    print(\"E2 — Distillation depuis un professeur jacobien (3 graines, tâche A, 1000 pas)\")\n    print(\"=\" * 78)\n    for kind in (\"mlp\", \"gauss\"):\n        sub = {m: [r for r in rows if r[\"parent\"] == kind and r[\"method\"] == m] for m in methods}\n        if not sub[\"gen\"]:\n            continue\n        print(f\"\\n--- parent {kind} (CE du professeur : \"\n              f\"{med([r['parent_val'] for r in sub['gen']]):.4f} nat) ---\")\n        print(f\"{'méthode':10} {'params W1':>10} {'KL@100':>8} {'KL@300':>8} {'KL final':>9} \"\n              f\"{'CE élève':>9} {'‖W1−W1*‖':>9}\")\n        for m in methods:\n            rs = sorted(sub[m], key=lambda r: r[\"seed\"])\n            if not rs:\n                continue\n            print(f\"{m:10} {rs[0]['ff1_params']:>10} \"\n                  f\"{med([r['kl_100'] for r in rs]):>8.4f} \"\n                  f\"{med([r['kl_300'] for r in rs]):>8.4f} \"\n                  f\"{med([r['final_kl'] for r in rs]):>9.4f} \"\n                  f\"{med([r['final_ce'] for r in rs]):>9.4f} \"\n                  f\"{med([np.mean(r['dist_to_parent_W1']) for r in rs]):>9.1%}\")\n        # apparié par graine : gen − concurrent (KL final)\n        print(\"\\nDifférences appariées par graine (KL final, gen − concurrent) :\")\n        for m in methods[1:]:\n            pairs = []\n            for s in (0, 1, 2):\n                a = [r for r in sub[\"gen\"] if r[\"seed\"] == s]\n                b = [r for r in sub[m] if r[\"seed\"] == s]\n                if a and b:\n                    pairs.append(a[0][\"final_kl\"] - b[0][\"final_kl\"])\n            if pairs:\n                wins = sum(x < 0 for x in pairs)\n                print(f\"  Δ(gen−{m:8}): médiane {med(pairs):+.4f}  \"\n                      f\"[{wins}/{len(pairs)} graines où gen gagne]\")\n        print(\"Différences appariées par graine (KL@300 — efficacité d'échantillons) :\")\n        for m in methods[1:]:\n            pairs = []\n            for s in (0, 1, 2):\n                a = [r for r in sub[\"gen\"] if r[\"seed\"] == s]\n                b = [r for r in sub[m] if r[\"seed\"] == s]\n                if a and b:\n                    pairs.append(a[0][\"kl_300\"] - b[0][\"kl_300\"])\n            if pairs:\n                wins = sum(x < 0 for x in pairs)\n                print(f\"  Δ(gen−{m:8}): médiane {med(pairs):+.4f}  \"\n                      f\"[{wins}/{len(pairs)} graines où gen gagne]\")\n\n\nif __name__ == \"__main__\":\n    e1_analysis()\n    e2_analysis()\n"